     1	const ISO_DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
     2	
     3	export const WEEKDAY_NAMES = [
     4	  'Sunday',
     5	  'Monday',
     6	  'Tuesday',
     7	  'Wednesday',
     8	  'Thursday',
     9	  'Friday',
    10	  'Saturday',
    11	];
    12	const MONTH_NAMES = [
    13	  'Jan',
    14	  'Feb',
    15	  'Mar',
    16	  'Apr',
    17	  'May',
    18	  'Jun',
    19	  'Jul',
    20	  'Aug',
    21	  'Sep',
    22	  'Oct',
    23	  'Nov',
    24	  'Dec',
    25	];
    26	
    27	/** Show date `<Weekday> <D> <Mon> <HH:mm>`, e.g. `Tuesday 15 Sep 16:00`. */
    28	export function formatShowDate(isoDate: string, time: string): string {
    29	  const date = parseIsoDate(isoDate);
    30	  if (!date) {
    31	    return `${isoDate} ${time}`;
    32	  }
    33	  return `${WEEKDAY_NAMES[date.getDay()]} ${date.getDate()} ${MONTH_NAMES[date.getMonth()]} ${time}`;
    34	}
    35	
    36	export function toIsoDate(date: Date): string {
    37	  const month = String(date.getMonth() + 1).padStart(2, '0');
    38	  const day = String(date.getDate()).padStart(2, '0');
    39	  return `${date.getFullYear()}-${month}-${day}`;
    40	}
    41	
    42	/** Returns the local date for a valid `YYYY-MM-DD` string, or null when it is not a real date. */
    43	export function parseIsoDate(value: string | null): Date | null {
    44	  if (!value || !ISO_DATE_PATTERN.test(value)) {
    45	    return null;
    46	  }
    47	  const [year, month, day] = value.split('-').map(Number);
    48	  const date = new Date(year, month - 1, day);
    49	  const isReal =
    50	    date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
    51	  return isReal ? date : null;
    52	}
    53	
    54	export function startOfToday(): Date {
    55	  const now = new Date();
    56	  return new Date(now.getFullYear(), now.getMonth(), now.getDate());
    57	}
    58	
    59	export function addDays(date: Date, days: number): Date {
    60	  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
    61	}
