     1	import { Injectable, inject } from '@angular/core';
     2	import { CanActivateFn, Router } from '@angular/router';
     3	import { COUCH_ROW, seatId } from './seat-selection/auditorium';
     4	import { COUCH_PRICE, seatPrice } from './pricing';
     5	import { CheckoutValues, EMPTY_CHECKOUT } from './checkout/checkout-rules';
     6	
     7	/** The booking in progress, kept in `sessionStorage` (section 3.1). */
     8	export interface Booking {
     9	  screeningId: number;
    10	  /** Seat identifiers; a couch contributes both of its identifiers. */
    11	  seats: string[];
    12	  /** The checkout form values, as typed (section 7.1). */
    13	  checkout: CheckoutValues;
    14	  /** The customer's email address once the booking is paid. */
    15	  paidEmail?: string;
    16	}
    17	
    18	/** One line of the summary: a single seat or a couch. */
    19	export interface TicketItem {
    20	  row: number;
    21	  /** `<column>` for a seat, `Couch <a>-<b>` for a couch. */
    22	  seat: string;
    23	  seatIds: string[];
    24	  price: number;
    25	}
    26	
    27	const STORAGE_KEY = 'cinescope.booking';
    28	const SEAT_ID_PATTERN = /^R(\d+)C(\d+)$/;
    29	
    30	@Injectable({ providedIn: 'root' })
    31	export class BookingStore {
    32	  read(): Booking | null {
    33	    const raw = sessionStorage.getItem(STORAGE_KEY);
    34	    if (raw === null) {
    35	      return null;
    36	    }
    37	    try {
    38	      const booking = JSON.parse(raw) as Partial<Booking>;
    39	      if (typeof booking.screeningId !== 'number' || !Array.isArray(booking.seats)) {
    40	        return null;
    41	      }
    42	      // Bookings stored before the checkout existed have no form values.
    43	      return {
    44	        screeningId: booking.screeningId,
    45	        seats: booking.seats,
    46	        checkout: { ...EMPTY_CHECKOUT, ...booking.checkout },
    47	        paidEmail: booking.paidEmail,
    48	      };
    49	    } catch {
    50	      return null;
    51	    }
    52	  }
    53	
    54	  write(booking: Booking): void {
    55	    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
    56	  }
    57	
    58	  clear(): void {
    59	    sessionStorage.removeItem(STORAGE_KEY);
    60	  }
    61	}
    62	
    63	/**
    64	 * Turns seat identifiers into the tickets of the summary, ordered by row and then by column.
    65	 * Couches only exist in the couch row, where they are always the pairs of columns 1–2, 3–4, …
    66	 */
    67	export function ticketsFor(seats: readonly string[]): TicketItem[] {
    68	  const columnsByRow = new Map<number, number[]>();
    69	  for (const id of seats) {
    70	    const match = SEAT_ID_PATTERN.exec(id);
    71	    if (!match) {
    72	      continue;
    73	    }
    74	    const row = Number(match[1]);
    75	    const columns = columnsByRow.get(row) ?? [];
    76	    columns.push(Number(match[2]));
    77	    columnsByRow.set(row, columns);
    78	  }
    79	
    80	  const items: TicketItem[] = [];
    81	  for (const row of [...columnsByRow.keys()].sort((a, b) => a - b)) {
    82	    const columns = (columnsByRow.get(row) ?? []).sort((a, b) => a - b);
    83	    for (let index = 0; index < columns.length; ) {
    84	      const column = columns[index];
    85	      const next = columns[index + 1];
    86	      if (row === COUCH_ROW && column % 2 === 1 && next === column + 1) {
    87	        items.push({
    88	          row,
    89	          seat: `Couch ${column}-${next}`,
    90	          seatIds: [seatId(row, column), seatId(row, next)],
    91	          price: COUCH_PRICE,
    92	        });
    93	        index += 2;
    94	      } else {
    95	        items.push({ row, seat: `${column}`, seatIds: [seatId(row, column)], price: seatPrice(row) });
    96	        index += 1;
    97	      }
    98	    }
    99	  }
   100	  return items;
   101	}
   102	
   103	/** A booking is paid once the checkout has stored the customer's email address in it. */
   104	export function isPaid(booking: Booking): boolean {
   105	  return booking.paidEmail !== undefined;
   106	}
   107	
   108	/**
   109	 * Lets a route be entered only with an unpaid booking in progress for the screening in the URL
   110	 * that has at least one seat (section 3.1).
   111	 */
   112	export const bookingInProgressGuard: CanActivateFn = (route) => {
   113	  const booking = inject(BookingStore).read();
   114	  const screeningId = Number(route.paramMap.get('id'));
   115	  if (
   116	    booking &&
   117	    !isPaid(booking) &&
   118	    booking.screeningId === screeningId &&
   119	    booking.seats.length > 0
   120	  ) {
   121	    return true;
   122	  }
   123	  return inject(Router).createUrlTree(['/']);
   124	};
   125	
   126	/** Lets a route be entered only once the booking in progress has been paid (section 3.1). */
   127	export const bookingPaidGuard: CanActivateFn = () => {
   128	  const booking = inject(BookingStore).read();
   129	  if (booking && isPaid(booking)) {
   130	    return true;
   131	  }
   132	  return inject(Router).createUrlTree(['/']);
   133	};
