    13	@Injectable({ providedIn: 'root' })
    14	export class CinemaApi {
    15	  private readonly http = inject(HttpClient);
    16	
    17	  movies(): Observable<Movie[]> {
    18	    return this.http.get<Movie[]>(`${API_BASE_URL}/movies`);
    19	  }
    20	
    21	  movie(id: number): Observable<Movie> {
    22	    return this.http.get<Movie>(`${API_BASE_URL}/movies/${id}`);
    23	  }
    24	
    25	  screeningsOn(date: string): Observable<Screening[]> {
    26	    return this.http.get<Screening[]>(`${API_BASE_URL}/screenings`, { params: { date } });
    27	  }
    28	
    29	  screening(id: string): Observable<Screening> {
    30	    return this.http.get<Screening>(`${API_BASE_URL}/screenings/${encodeURIComponent(id)}`);
    31	  }
    32	
    33	  createReservation(reservation: NewReservation): Observable<Reservation> {
    34	    return this.http.post<Reservation>(`${API_BASE_URL}/reservations`, reservation);
    35	  }
    36	
    37	  /** A screening together with its movie; fails when either request fails. */
    38	  screeningWithMovie(id: string): Observable<ScreeningWithMovie> {
    39	    return this.screening(id).pipe(
    40	      switchMap((screening) =>
    41	        this.movie(screening.movieId).pipe(map((movie) => ({ screening, movie }))),
    42	      ),
    43	    );
    44	  }
    45	}
