     8	import { ActivatedRoute, Router } from '@angular/router';
     9	import { catchError, forkJoin, map, of, startWith, switchMap } from 'rxjs';
    10	import { CinemaApi } from '../cinema-api.service';
    11	import { WEEKDAY_NAMES, addDays, parseIsoDate, startOfToday, toIsoDate } from '../dates';
    12	import { Movie, Screening } from '../models';
    13	
    14	interface DayButton {
    15	  iso: string;
    16	  label: string;
    17	}
    18	
    19	interface MovieWithScreenings {
    20	  movie: Movie;
    21	  screenings: Screening[];
    22	}
    23	
    24	type MovieListState =
    25	  | { status: 'loading' }
    26	  | { status: 'error' }
    27	  | { status: 'loaded'; movies: MovieWithScreenings[] };
    28	
    29	@Component({
    30	  selector: 'app-movie-list',
    31	  imports: [MatButtonModule, MatDatepickerModule, MatFormFieldModule, MatInputModule, MatProgressSpinnerModule],
    32	  templateUrl: './movie-list.html',
    33	  styleUrl: './movie-list.scss',
    34	})
    35	export class MovieList {
    36	  private readonly api = inject(CinemaApi);
    37	  private readonly router = inject(Router);
    38	  private readonly route = inject(ActivatedRoute);
    39	
    40	  private readonly todayDate = startOfToday();
    41	  private readonly todayIso = toIsoDate(this.todayDate);
    42	
    43	  readonly todayPickerMin = this.todayDate;
    44	  readonly dayButtons: DayButton[] = Array.from({ length: 5 }, (_, offset) => {
    45	    const date = addDays(this.todayDate, offset);
    46	    return {
    47	      iso: toIsoDate(date),
    48	      label: offset === 0 ? 'Today' : WEEKDAY_NAMES[date.getDay()],
    49	    };
    50	  });
    51	
    52	  private readonly queryDate = toSignal(
    53	    this.route.queryParamMap.pipe(map((params) => params.get('date'))),
    54	    { initialValue: null },
    55	  );
    56	
    57	  /** `?date=` when it is a real date that is not in the past, otherwise today. */
    58	  readonly selectedDate = computed(() => {
    59	    const requested = this.queryDate();
    60	    const isUsable = parseIsoDate(requested) !== null && requested !== null && requested >= this.todayIso;
    61	    return isUsable ? requested : this.todayIso;
    62	  });
    63	
    64	  /** The datepicker shows the date only when it is not one of the five day buttons. */
    65	  readonly pickerValue = computed(() => {
    66	    const selected = this.selectedDate();
    67	    return this.dayButtons.some((day) => day.iso === selected) ? null : parseIsoDate(selected);
    68	  });
    69	
    70	  private readonly attempt = signal(0);
    71	
    72	  private readonly request = computed(() => ({ date: this.selectedDate(), attempt: this.attempt() }));
    73	
    74	  readonly state = toSignal<MovieListState, MovieListState>(
    75	    toObservable(this.request).pipe(
    76	      switchMap(({ date }) =>
    77	        forkJoin({ movies: this.api.movies(), screenings: this.api.screeningsOn(date) }).pipe(
    78	          map(({ movies, screenings }) => ({
    79	            status: 'loaded' as const,
    80	            movies: groupScreenings(movies, screenings),
    81	          })),
    82	          startWith<MovieListState>({ status: 'loading' }),
    83	          catchError(() => of<MovieListState>({ status: 'error' })),
    84	        ),
    85	      ),
    86	    ),
    87	    { initialValue: { status: 'loading' } },
    88	  );
    89	
    90	  isSelected(day: DayButton): boolean {
    91	    return day.iso === this.selectedDate();
    92	  }
    93	
    94	  chooseDate(iso: string | null): void {
    95	    this.router.navigate([], { relativeTo: this.route, queryParams: { date: iso } });
    96	  }
    97	
    98	  onDatePicked(event: MatDatepickerInputEvent<Date>): void {
    99	    this.chooseDate(event.value ? toIsoDate(event.value) : null);
   100	  }
   101	
   102	  retry(): void {
   103	    this.attempt.update((count) => count + 1);
   104	  }
   105	
   106	  openScreening(id: number): void {
   107	    this.router.navigate(['/screenings', id, 'seats']);
   108	  }
   109	}
   110	
   111	function groupScreenings(movies: Movie[], screenings: Screening[]): MovieWithScreenings[] {
   112	  const byMovie = new Map<number, Screening[]>();
   113	  for (const screening of screenings) {
   114	    byMovie.set(screening.movieId, [...(byMovie.get(screening.movieId) ?? []), screening]);
   115	  }
   116	  return movies.flatMap((movie) => {
   117	    const movieScreenings = (byMovie.get(movie.id) ?? []).sort((a, b) => a.time.localeCompare(b.time));
   118	    return movieScreenings.length > 0 ? [{ movie, screenings: movieScreenings }] : [];
   119	  });
   120	}
