    42	/**
    43	 * Builds the auditorium from top (row 1, next to the screen) to bottom. Each row lists its
    44	 * cells from left to right: the left block (columns 1–4, or the entrance in rows 1–10), an
    45	 * aisle, columns 5–20, an aisle and columns 21–24. Row 15 is made of couches.
    46	 */
    47	export function buildAuditorium(occupiedSeats: readonly string[]): AuditoriumRow[] {
    48	  const occupied = new Set(occupiedSeats);
    49	  return Array.from({ length: ROW_COUNT }, (_, index) => {
    50	    const row = index + 1;
    51	    const left: AuditoriumCell[] =
    52	      row <= LAST_ENTRANCE_ROW ? [{ kind: 'entrance' }] : blockCells(row, 1, 4, occupied);
    53	    return {
    54	      row,
    55	      cells: [
    56	        ...left,
    57	        { kind: 'aisle', row },
    58	        ...blockCells(row, 5, 20, occupied),
    59	        { kind: 'aisle', row },
    60	        ...blockCells(row, 21, 24, occupied),
    61	      ],
    62	    };
    63	  });
