    83	  const cells: AuditoriumCell[] = [];
    84	  for (let column = firstColumn; column <= lastColumn;) {
    85	    if (row === COUCH_ROW) {
    86	      cells.push(couchCell(row, column, occupied));
    87	      column += 2;
    88	    } else {
    89	      cells.push(seatCell(row, column, occupied));
    90	      column += 1;
    91	    }
    92	  }
    93	  return cells;
    94	}
    95	
    96	function seatCell(row: number, column: number, occupied: ReadonlySet<string>): SeatCell {
    97	  let state: SeatState = 'available';
    98	  if (occupied.has(seatId(row, column))) {
    99	    state = 'unavailable';
   100	  } else if (isAccessible(row, column)) {
   101	    state = 'accessible';
   102	  }
   103	  return { kind: 'seat', row, column, state };
   104	}
   105	
   106	function couchCell(row: number, columnStart: number, occupied: ReadonlySet<string>): CouchCell {
   107	  const columnEnd = columnStart + 1;
   108	  const isOccupied = occupied.has(seatId(row, columnStart)) || occupied.has(seatId(row, columnEnd));
   109	  return {
   110	    kind: 'couch',
   111	    row,
   112	    columnStart,
   113	    columnEnd,
   114	    state: isOccupied ? 'unavailable' : 'available',
   115	  };
   116	}
   117	
   118	function isAccessible(row: number, column: number): boolean {
   119	  return (
   120	    row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN
   121	  );
   122	}
