    36	  readonly formatPrice = formatPrice;
    37	
    38	  /** The form values; saved in the booking as they change (section 7.1). */
    39	  readonly values = signal<CheckoutValues>(this.initial?.checkout ?? EMPTY_CHECKOUT);
    40	
    41	  /** Fields that have been left at least once, or that `Pay` has marked. */
    42	  private readonly touched = signal<ReadonlySet<CheckoutField>>(new Set());
    43	
    44	  /** True while the reservation request is in flight. */
    45	  readonly submitting = signal(false);
    46	
    47	  private readonly errors = computed(() => validateCheckout(this.values()));
    48	
    49	  readonly total = ticketsFor(this.initial?.seats ?? []).reduce((sum, item) => sum + item.price, 0);
    50	
    51	  /** The message of a field, shown only once the field has been left. */
    52	  message(field: CheckoutField): string | null {
    53	    return this.touched().has(field) ? (this.errors()[field] ?? null) : null;
    54	  }
    55	
    56	  onInput(field: TextField, event: Event): void {
    57	    this.setValue(field, (event.target as HTMLInputElement).value);
    58	  }
