    60	  onTermsChange(checked: boolean): void {
    61	    this.setValue('terms', checked);
    62	    this.touch('terms');
    63	  }
    64	
    65	  touch(field: CheckoutField): void {
    66	    this.touched.update((fields) => new Set(fields).add(field));
    67	  }
