   115	  private setValue<K extends keyof CheckoutValues>(field: K, value: CheckoutValues[K]): void {
   116	    const next = { ...this.values(), [field]: value };
   117	    this.values.set(next);
   118	    const booking = this.bookings.read();
   119	    if (booking) {
   120	      this.bookings.write({ ...booking, checkout: next });
   121	    }
   122	  }
